// ---------------------------------------------------------------------------
// D. Tectonics::query — ALL scalar fields
// ---------------------------------------------------------------------------

#[test]
fn golden_tectonics_query() {
    let g = load_golden();
    let p = &g.params;
    let tect = Tectonics::new(
        p.seed,
        p.plate_count,
        p.arc_density,
        p.hotspot_count,
        p.hotspot_intensity,
    );

    let mut failures = Vec::new();

    for (i, s) in g.tectonics_samples.iter().enumerate() {
        let dir = DVec3::new(s.x, s.y, s.z);
        let q = tect.query(dir);

        // Integer fields: exact match
        if q.plate_id != s.plate_id {
            failures.push(format!(
                "  tect[{i}] ({x:.6},{y:.6},{z:.6}): plate_id expected {}, got {}",
                s.plate_id, q.plate_id, x=s.x, y=s.y, z=s.z
            ));
        }
        if q.neighbor_id != s.neighbor_id {
            failures.push(format!(
                "  tect[{i}] ({x:.6},{y:.6},{z:.6}): neighbor_id expected {}, got {}",
                s.neighbor_id, q.neighbor_id, x=s.x, y=s.y, z=s.z
            ));
        }

        // Scalar fields: < 1e-9
        let check = |name: &str, exp: f64, act: f64| -> Option<String> {
            let err = (act - exp).abs();
            if err > TECT_TOL {
                Some(format!(
                    "  tect[{i}] ({x:.6},{y:.6},{z:.6}) {name}: expected {exp:.17e}, got {act:.17e}, err={err:.3e}",
                    x=s.x, y=s.y, z=s.z
                ))
            } else { None }
        };

        if let Some(f) = check("boundary_dist", s.boundary_dist, q.boundary_dist)    { failures.push(f); }
        if let Some(f) = check("convergence",   s.convergence,   q.convergence)       { failures.push(f); }
        if let Some(f) = check("shear",         s.shear,         q.shear)             { failures.push(f); }
        if let Some(f) = check("crust_dist",    s.crust_dist,    q.crust_dist)        { failures.push(f); }
        if let Some(f) = check("paleo_dist",    s.paleo_dist,    q.paleo_dist)        { failures.push(f); }
        if let Some(f) = check("other_crust_dist", s.other_crust_dist, q.other_crust_dist) { failures.push(f); }
    }

    if !failures.is_empty() {
        panic!(
            "FAIL: Tectonics::query diverged from golden ({} field failures over {} samples):\n{}",
            failures.len(), g.tectonics_samples.len(),
            failures.join("\n")
        );
    }
    println!("PASS: Tectonics::query — {} samples within {TECT_TOL:.0e}", g.tectonics_samples.len());
}

// ---------------------------------------------------------------------------
// E. TectonicHeightField::height — additive-octave LOD invariant
// ---------------------------------------------------------------------------

#[test]
fn golden_height_and_lod_invariant() {
    let g = load_golden();
    let p = &g.params;

    let hf = TectonicHeightField::new(TectonicHeightFieldParams {
        seed:              p.seed,
        plate_count:       p.plate_count,
        arc_density:       p.arc_density,
        hotspot_count:     p.hotspot_count,
        hotspot_intensity: p.hotspot_intensity,
        climate: ClimateParams {
            seed:           p.seed,
            base_temp:      p.base_temp,
            atmosphere:     p.atmosphere,
            band_count:     p.band_count,
            axial_tilt_rad: p.axial_tilt_deg.to_radians(),
            redistribution: None,
            greenhouse:     None,
            lapse_rate:     None,
        },
    });

    let mut failures = Vec::new();

    for (i, s) in g.height_samples.iter().enumerate() {
        let dir = DVec3::new(s.x, s.y, s.z);
        let actual = hf.height(dir, s.level);
        let err = (actual - s.value).abs();
        if err > HEIGHT_TOL {
            failures.push(format!(
                "  height[{i}] ({x:.6},{y:.6},{z:.6}) level={lv}: expected {exp:.17e}, got {act:.17e}, err={err:.3e}",
                x=s.x, y=s.y, z=s.z, lv=s.level,
                exp=s.value, act=actual,
            ));
        }
    }

    if !failures.is_empty() {
        panic!(
            "FAIL: TectonicHeightField::height diverged from golden ({}/{} vectors):\n{}",
            failures.len(), g.height_samples.len(),
            failures.join("\n")
        );
    }

    // Additional LOD invariant check from the golden itself:
    // For each spatial position (same x,y,z), levels 0 and 4 share the same
    // 6 base FBM octaves — so height(level=4) - height(level=0) should be ≤ 0.04
    // (at most one extra fbm octave amplitude: 0.5^6/MAX_AMP_FBM6 ≈ 0.016 * TECT_DETAIL_FBM_BASE ≈ 0.0016).
    // We verify it also holds in the goldens (catching any TS-side LOD drift).
    let level_groups: Vec<_> = g.height_samples.chunks(4).collect(); // 4 levels per dir
    let mut lod_failures = Vec::new();
    for (gi, group) in level_groups.iter().enumerate() {
        if group.len() < 2 { continue; }
        let h0 = group[0].value; // level 0
        let h4 = group[1].value; // level 4
        let diff = (h4 - h0).abs();
        if diff > 0.04 {
            lod_failures.push(format!(
                "  LOD invariant failed at dir[{gi}] ({x:.6},{y:.6},{z:.6}): |h(lv=4)-h(lv=0)|={diff:.4} > 0.04",
                x=group[0].x, y=group[0].y, z=group[0].z,
            ));
        }
    }
    if !lod_failures.is_empty() {
        panic!("FAIL: LOD additive-octave invariant violated in GOLDEN data ({} dirs):\n{}",
            lod_failures.len(), lod_failures.join("\n"));
    }

    println!("PASS: TectonicHeightField::height — {} vectors within {HEIGHT_TOL:.0e}", g.height_samples.len());
    println!("PASS: LOD additive-octave invariant — {} position groups", level_groups.len());
}
